import{_ as s,o as e,c as t,a3 as n}from"./chunks/framework.BqYSQyk_.js";const g=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"developers/examples.md","filePath":"developers/examples.md"}'),p={name:"developers/examples.md"};function i(o,a,c,l,d,r){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>All of these run as written with <code>--loopback</code>. Against a board, drop <code>--loopback</code> or pass <code>--usb</code>, and add <code>--yes</code> on destructive lines if you are not in a TTY.</p><p><code>--loopback</code> is per process: chain steps with <code>repl</code> or <code>--script</code>, not separate shells.</p><h2 id="hello-→-list-→-pull-push" tabindex="-1">Hello → list → pull / push <a class="header-anchor" href="#hello-→-list-→-pull-push" aria-label="Permalink to &quot;Hello → list → pull / push&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>One process for the transfer:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; pull internal 1 /tmp/p1.s32p</span></span>
<span class="line"><span>s32&gt; push /tmp/p1.s32p</span></span>
<span class="line"><span>s32&gt; active</span></span>
<span class="line"><span>s32&gt; push /tmp/p1.s32p --activate</span></span>
<span class="line"><span>s32&gt; active</span></span></code></pre></div><h2 id="edit-a-cc-macro" tabindex="-1">Edit a CC macro <a class="header-anchor" href="#edit-a-cc-macro" aria-label="Permalink to &quot;Edit a CC macro&quot;">​</a></h2><p>Each knob has four macros. Modes use names, not integers — see <a href="./commands/macros">Macros</a>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; macro get 4 1</span></span>
<span class="line"><span>s32&gt; macro set 4 1 mode=cc msb=74 channel=3</span></span>
<span class="line"><span>s32&gt; macro get 4 1</span></span>
<span class="line"><span>s32&gt; potname set 4 Cutoff</span></span></code></pre></div><p>Route a knob to a rack device parameter:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; macro set 4 0 mode=device rack=100 device=1000 param=bypass min=0 max=1</span></span></code></pre></div><p>Assign an LFO to the same ParameterId. <code>param=</code> follows <code>target</code>: ParameterId names for <code>device</code>, LFO names for <code>target=lfo</code>. Macro targets use <code>pot=</code> / <code>macro=</code> (0–31 / 0–3), not <code>rack</code> / <code>device</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; lfo assign add 0 target=device rack=100 device=1000 param=bypass min=0 max=1</span></span>
<span class="line"><span>s32&gt; lfo assign add 0 target=lfo targetLfo=1 param=amplitude min=0 max=1</span></span>
<span class="line"><span>s32&gt; lfo assign add 0 target=macro pot=2 macro=1 min=0 max=1</span></span></code></pre></div><h2 id="add-a-device" tabindex="-1">Add a device <a class="header-anchor" href="#add-a-device" aria-label="Permalink to &quot;Add a device&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; schema</span></span>
<span class="line"><span>s32&gt; rack list</span></span>
<span class="line"><span>s32&gt; device list 0</span></span>
<span class="line"><span>s32&gt; device add 0 clock</span></span>
<span class="line"><span>s32&gt; device param set 0 1 bypass 1</span></span>
<span class="line"><span>s32&gt; device param get 0 1 bypass</span></span></code></pre></div><p><code>device add</code> takes a type <strong>name</strong> (<code>clock</code>, <code>midi-in</code>, <code>step-seq</code>, …) or the numeric schema id. <code>device param</code> uses <strong>ParameterId</strong> (<code>bypass</code> is 0). On hardware, Clock’s division control is <code>clock-division</code>, not slot <code>1</code> (<code>1</code> is <code>MODE</code>).</p><h2 id="screen-png" tabindex="-1">Screen PNG <a class="header-anchor" href="#screen-png" aria-label="Permalink to &quot;Screen PNG&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; view nav racks</span></span>
<span class="line"><span>s32&gt; view nav s32-lfo index=5</span></span>
<span class="line"><span>s32&gt; screen png /tmp/oled.png</span></span></code></pre></div><h2 id="watch-pots" tabindex="-1">Watch pots <a class="header-anchor" href="#watch-pots" aria-label="Permalink to &quot;Watch pots&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>Turn knobs on the hardware. The simulator has no physical pots; <code>watch</code> still prints events produced by earlier edits in the same process.</p>`,22)])])}const m=s(p,[["render",i]]);export{g as __pageData,m as default};
